 passScene.add(new T.Mesh(new T.PlaneGeometry(2,2),material));
 return {material,stats,render(scene,cam,width,height,ratio){renderer.getSize(logicalSize);if(renderer.getPixelRatio()!==ratio||logicalSize.x!==width||logicalSize.y!==height||renderer.domElement.width!==Math.floor(width*ratio)||renderer.domElement.height!==Math.floor(height*ratio))renderer.setDrawingBufferSize(width,height,ratio);if(target.width!==renderer.domElement.width||target.height!==renderer.domElement.height)target.setSize(renderer.domElement.width,renderer.domElement.height);material.uniforms.resolution.value.set(target.width,target.height);material.uniforms.inverseProjection.value.copy(cam.projectionMatrixInverse);material.uniforms.projection.value.copy(cam.projectionMatrix);material.uniforms.sunView.value.copy(material.uniforms.sunDirection.value).transformDirection(cam.matrixWorldInverse);renderer.setRenderTarget(target);renderer.render(scene,cam);if(stats){stats.worldCalls=renderer.info.render.calls;stats.worldTriangles=renderer.info.render.triangles;stats.width=target.width;stats.height=target.height;}renderer.setRenderTarget(null);renderer.render(passScene,camera);if(stats)stats.postCalls=renderer.info.render.calls;}};
